DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaSebraUpdateTablaCartera"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaSebraUpdateTablaCartera"
 AFTER   UPDATE ON "BSCL.Custodia.BD::CUS.Cartera"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN

	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."FolioCartera" AS varchar(200)),'FMCarteraForward', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY WHERE :NewRow."IdTipoProducto" = 'MEFW';
 END;

DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaSebraUpdateTablaCuentaBancaria"; GO

