 -- CARTERA

DROP TRIGGER  "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCartera"; GO

CREATE TRIGGER "BSCL.Plataforma.BD::PLA.Replica.TriggerReplicaInsertTablaCartera"
 AFTER   INSERT ON "BSCL.Custodia.BD::CUS.Cartera"
 REFERENCING NEW ROW NewRow FOR EACH ROW 
 BEGIN 
 	
 	INSERT INTO "BSCL.Plataforma.BD::PLA.Replica.WorkStack"("Key", "Table","Action" , "Status", "Stamp"  )
	SELECT cast(:NewRow."FolioCartera" AS varchar(200)),concat('TBCTCU' , :NewRow."IdClasificacionTipoInstrumento"), 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" = 'RV'  OR :NewRow."IdClasificacionTipoInstrumento" = 'RF' OR :NewRow."IdClasificacionTipoInstrumento" = 'FM'
	union
	SELECT cast(:NewRow."FolioCartera" AS varchar(200)),concat('TBCTCI' , :NewRow."IdClasificacionTipoInstrumento"), 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" = 'RV'  OR :NewRow."IdClasificacionTipoInstrumento" = 'RF' OR :NewRow."IdClasificacionTipoInstrumento" = 'FM' OR :NewRow."IdClasificacionTipoInstrumento" = 'IF'
	union
	SELECT cast(:NewRow."FolioCartera" AS varchar(200)),'TBCTTRTP', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" = 'RV' AND :NewRow."IdTipoInstrumento" = 'SIM'
	union
	SELECT cast(:NewRow."FolioCartera" AS varchar(200)),'TBCTTRCO', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdTipoInstrumento" = 'PRT' AND :NewRow."IdTipoPrestamo" = 'PRTVTC'
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_Cartera', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY
	union
	SELECT cast(:NewRow."IdPortafolio" AS varchar(200)) || ':' ||  cast(:NewRow."Nemotecnico" AS varchar(200)),'Custodia_CustodiaFechaLiquidacion', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY
	union
	SELECT cast(:NewRow."IdPortafolio" AS varchar(200)) || ':' ||  cast(:NewRow."Nemotecnico" AS varchar(200)),'Custodia_CustodiaFechaOperacion', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraFM', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" = 'FM'
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraOtrosProductos', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" NOT IN('FM','RV','RF','IF')
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraRFIF', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" IN('RF','IF')
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_CarteraRV', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY where :NewRow."IdClasificacionTipoInstrumento" = 'RV'
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_MovimientoCarteraIngresos', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY
	union
	SELECT cast(:NewRow."IdCartera" AS varchar(200)),'Custodia_MovimientoCarteraEgresos', 'A', 0,  CURRENT_TIMESTAMP  FROM DUMMY;
END; GO

