        	v_accion = 'D';
        end if; 

	 	CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
			(  
					cast(:NewRow."IdDireccionElectronica" AS varchar(200))  
					,'DIRECCION_ELECTRONICA'
					,:v_accion
		    ); 
 
		CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
			(  
					cast(:NewRow."IdPersona" AS varchar(200))  
					,'USO_DIRECCIONES'
					,:v_accion
		    );
		   
		CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
				(  
						cast(:NewRow."IdDireccionElectronica" AS varchar(200))  
						,'SocioNegocio_PersonaDireccionElectronica'
						,:v_accion
			    );

 END; GO

