							,'A'
				    ); 
	 	
	 	
		 	CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
					(  
							cast(:NewRow."IdOperacion" AS varchar(200))  
							,'FMCarteraForward'
							,'A'
				    ); 				    

	    end if; 
	 
	 	IF (:NewRow."IdTipoProducto" = 'MERF')  then

		 	CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
					(  
							cast(:NewRow."IdOperacion" AS varchar(200))  
							,'TBCPMSPC'
							,'A'
				    ); 
				    
				    
				CALL "BSCL.Replica.BD.Servicios::InsertWorkStack"
				(  
						cast(:NewRow."IdOperacion" AS varchar(200))  
